begin;
set local search_path=public,extensions;
select no_plan();
select has_table('public','subscription_trial_activation_attempts','external create admission is durable');
insert into public.users(id,email,display_name) values ('d1000000-0000-4000-8000-000000000001','activation-guard@example.test','Guard');
update public.hosting_commercial_policy set activation_at=now()-interval '1 day',trials_enabled=true,cardless_trials_enabled=true;
create temporary table guard_proof(name text primary key,value jsonb);
grant all on guard_proof to service_role;
set local role service_role;
insert into guard_proof values('a',public.reserve_cardless_trial_v1('d1000000-0000-4000-8000-000000000001',gen_random_uuid(),'plus','monthly','price_plus',null,1));
insert into guard_proof values('attempt',to_jsonb(public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),'customer','trial-customer:'||(select value->>'id' from guard_proof where name='a'))));
select throws_ok($$select public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),'customer','trial-customer:'||(select value->>'id' from guard_proof where name='a'))$$,'P0001','TRIAL_ATTEMPT_BUSY','parallel admission cannot outlive an unrecorded result');
reset role;
select ok(not has_function_privilege('service_role','anidachi_private.hold_cardless_trial_activation_v1(uuid,uuid,text,boolean)','EXECUTE'),'runtime cannot place or remove an operator hold');
reset role;
select anidachi_private.hold_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select value->>'idempotency_key' from guard_proof where name='a'),true);
select throws_ok($$select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select value->>'idempotency_key' from guard_proof where name='a'),(select (value->>'created_at')::timestamptz from guard_proof where name='a'),'Verified provider logs and frozen invocation evidence for fixture')$$,'P0001','TRIAL_ATTEMPT_UNRESOLVED','lost begin receipt or paused caller blocks terminal settlement');
set local role service_role;
select throws_ok($$select public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),'customer','trial-customer:'||(select value->>'id' from guard_proof where name='a'))$$,'P0001','TRIAL_RECOVERY_HELD','old recovery snapshot cannot start after hold');
select public.finish_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select (value#>>'{}')::uuid from guard_proof where name='attempt'),'unknown',null,'req_fixture_failure');
reset role;
select throws_ok($$select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select value->>'idempotency_key' from guard_proof where name='a'),(select (value->>'created_at')::timestamptz from guard_proof where name='a'),'Verified provider logs and frozen invocation evidence for fixture')$$,'P0001','TRIAL_ATTEMPT_UNRESOLVED','finished invocation does not prove provider failure');
select throws_ok($$select anidachi_private.reconcile_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select (value#>>'{}')::uuid from guard_proof where name='attempt'),'no_effect',null,'req_fixture_failure','Provider request positively rejected before creating any object','All guarded invocations verified terminated; old deployments retired')$$,'P0001','TRIAL_RECOVERY_DRAIN_REQUIRED','manual evidence also requires a bounded executor drain');
update public.subscription_trial_activations set recovery_hold_at=now()-interval '6 minutes';
select anidachi_private.reconcile_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select (value#>>'{}')::uuid from guard_proof where name='attempt'),'no_effect',null,'req_fixture_failure','Provider request positively rejected before creating any object','All guarded invocations verified terminated; old deployments retired');
select throws_ok($$select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),'foreign-key',(select (value->>'created_at')::timestamptz from guard_proof where name='a'),'Verified provider logs and frozen invocation evidence for fixture')$$,'P0001','TRIAL_ACTIVATION_MISMATCH','frozen identity prevents settlement of another operation');
select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),(select value->>'idempotency_key' from guard_proof where name='a'),(select (value->>'created_at')::timestamptz from guard_proof where name='a'),'Verified provider logs and frozen invocation evidence for fixture');
select is((select state from public.subscription_trial_activations),'failed','only positively reconciled failed operation releases account authority');
select is((select count(*) from public.account_subscription_trials),0::bigint,'failed activation does not spend the trial');
select ok((select count(*)>=3 from anidachi_private.trial_activation_recovery_audit),'hold, evidence and terminal transition are audited');
set local role service_role;
select throws_ok($$select public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='a'),'customer','trial-customer:'||(select value->>'id' from guard_proof where name='a'))$$,'P0001','TRIAL_ACTIVATION_STALE','late old recovery cannot issue create after settlement');
insert into guard_proof values('b',public.reserve_cardless_trial_v1('d1000000-0000-4000-8000-000000000001',gen_random_uuid(),'pro','monthly','price_pro',null,1));
select isnt((select value->>'id' from guard_proof where name='a'),(select value->>'id' from guard_proof where name='b'),'a fresh explicit trial can be reserved after verified no-effect settlement');
select public.record_cardless_trial_customer_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='b'),'cus_guard');
insert into guard_proof values('schedule-attempt',to_jsonb(public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='b'),'schedule',(select value->>'idempotency_key' from guard_proof where name='b'))));
select public.finish_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='b'),(select (value#>>'{}')::uuid from guard_proof where name='schedule-attempt'),'succeeded','sub_sched_guard','req_success');
reset role;
select anidachi_private.hold_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='b'),(select value->>'idempotency_key' from guard_proof where name='b'),true);
select throws_ok($$select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from guard_proof where name='b'),(select value->>'idempotency_key' from guard_proof where name='b'),(select (value->>'created_at')::timestamptz from guard_proof where name='b'),'Verified provider logs and frozen invocation evidence for fixture')$$,'P0001','TRIAL_EXTERNAL_EFFECT_EXISTS','success before recordCreated or a lost response only allows object recovery');
set local role authenticated;
select throws_ok($$select * from public.subscription_trial_activation_attempts$$,'42501',null,'clients cannot inspect private attempts');
reset role;
-- Lost begin receipt / crash before dispatch: only explicit no-dispatch and stopped-executor evidence can close it.
insert into public.users(id,email,display_name) values ('d1000000-0000-4000-8000-000000000002','activation-abandoned@example.test','Abandoned');
insert into guard_proof values('c',public.reserve_cardless_trial_v1('d1000000-0000-4000-8000-000000000002',gen_random_uuid(),'plus','monthly','price_plus',null,1));
insert into guard_proof values('abandoned',to_jsonb(public.begin_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),'customer','trial-customer:'||(select value->>'id' from guard_proof where name='c'))));
select anidachi_private.hold_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),(select value->>'idempotency_key' from guard_proof where name='c'),true);
update public.subscription_trial_activations set recovery_hold_at=now()-interval '6 minutes' where user_id='d1000000-0000-4000-8000-000000000002';
select throws_ok($$select anidachi_private.reconcile_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),(select (value#>>'{}')::uuid from guard_proof where name='abandoned'),'no_effect',null,null,'timeout','All guarded invocations verified terminated; old deployments retired')$$,'P0001','TRIAL_RECOVERY_EVIDENCE_REQUIRED','elapsed hold and stopped executor alone never prove the provider outcome');
select anidachi_private.reconcile_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),(select (value#>>'{}')::uuid from guard_proof where name='abandoned'),'no_effect',null,null,'Invocation trace confirms no dispatch; lost begin receipt and no provider request','All guarded invocations verified terminated; old deployments retired');
select anidachi_private.settle_cardless_trial_activation_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),(select value->>'idempotency_key' from guard_proof where name='c'),(select (value->>'created_at')::timestamptz from guard_proof where name='c'),'Audited no-dispatch recovery covers every issued permit for this activation');
select is((select state from public.subscription_trial_activations where user_id='d1000000-0000-4000-8000-000000000002'),'failed','abandoned applying has a reviewed terminal path');
set local role service_role;
select throws_ok($$select public.finish_cardless_trial_attempt_v1('d1000000-0000-4000-8000-000000000002',(select (value->>'id')::uuid from guard_proof where name='c'),(select (value#>>'{}')::uuid from guard_proof where name='abandoned'),'succeeded','cus_late','req_late')$$,'P0001','TRIAL_ATTEMPT_STALE','an old response cannot silently rewrite operator evidence');
reset role;
select * from finish();
rollback;
